create table public.app_settings(key text primary key,value text not null);
create table public.profiles(id uuid primary key references auth.users on delete cascade,student_code text unique not null check(student_code ~ '^[0-9]{2}-[0-9]{2}-[0-9]{3}$'),full_name text not null check(length(full_name) between 2 and 100),phone text not null,role text not null default 'student' check(role in ('student','leader')),recovery_hash text not null,created_at timestamptz not null default now());
create table public.identities(user_id uuid primary key references public.profiles on delete cascade,ciphertext text not null,updated_at timestamptz not null default now());
create table public.events(id uuid primary key default gen_random_uuid(),title text not null,description text not null default '',location text not null,start_at timestamptz not null,end_at timestamptz not null,points integer not null check(points between 0 and 10000),cover_url text,qr_hash text not null,created_by uuid references public.profiles,created_at timestamptz not null default now(),check(end_at>start_at));
create index events_start on public.events(start_at);
create table public.registrations(event_id uuid references public.events on delete cascade,user_id uuid references public.profiles on delete cascade,going boolean not null default true,accommodation text not null default '',excuse text not null default '',request_status text not null default 'accepted' check(request_status='accepted'),created_at timestamptz not null default now(),primary key(event_id,user_id));
create index registrations_user on public.registrations(user_id);
create table public.attendance(event_id uuid references public.events on delete cascade,user_id uuid references public.profiles on delete cascade,checked_at timestamptz not null default now(),actor_id uuid references public.profiles,primary key(event_id,user_id));
create index attendance_user on public.attendance(user_id);
create table public.points_ledger(event_id uuid references public.events on delete cascade,user_id uuid references public.profiles on delete cascade,points integer not null,created_at timestamptz not null default now(),primary key(event_id,user_id));
create index points_user on public.points_ledger(user_id);
create table public.news(id uuid primary key default gen_random_uuid(),title text not null,body text not null,created_at timestamptz not null default now());
create table public.rate_limits(key text primary key,hits integer not null,expires timestamptz not null);
create or replace function public.take_rate_limit(p_key text,p_limit integer,p_seconds integer) returns boolean language plpgsql set search_path='' as $$ declare n integer; begin insert into public.rate_limits(key,hits,expires) values(p_key,1,now()+make_interval(secs=>p_seconds)) on conflict(key) do update set hits=case when public.rate_limits.expires<now() then 1 else public.rate_limits.hits+1 end,expires=case when public.rate_limits.expires<now() then now()+make_interval(secs=>p_seconds) else public.rate_limits.expires end returning hits into n; return n<=p_limit; end $$;
create or replace function public.check_in(p_event uuid,p_user uuid,p_actor uuid,p_qr text default null) returns jsonb language plpgsql set search_path='' as $$ declare ev public.events; awarded integer; begin select * into ev from public.events where id=p_event for share; if ev.id is null then raise exception 'Event not found'; end if; if now()<ev.start_at-interval '60 minutes' or now()>ev.end_at+interval '60 minutes' then raise exception 'Attendance is not open'; end if; if p_actor=p_user then if p_qr is null or p_qr<>ev.qr_hash then raise exception 'Invalid QR'; end if; if not exists(select 1 from public.registrations where event_id=p_event and user_id=p_user and going) then raise exception 'Register for this event first'; end if; elsif not exists(select 1 from public.profiles where id=p_actor and role='leader') then raise exception 'Forbidden'; end if; insert into public.attendance(event_id,user_id,actor_id) values(p_event,p_user,p_actor) on conflict do nothing; insert into public.points_ledger(event_id,user_id,points) values(p_event,p_user,ev.points) on conflict do nothing returning points into awarded; return jsonb_build_object('saved',true,'points',coalesce(awarded,0),'alreadyRecorded',awarded is null); end $$;
create or replace function public.leaderboard() returns table(full_name text,points bigint) language sql stable set search_path='' as $$ select p.full_name,coalesce(sum(l.points),0)::bigint from public.profiles p left join public.points_ledger l on l.user_id=p.id group by p.id,p.full_name order by 2 desc,p.full_name limit 100 $$;
-- All access goes through the authenticated server gateway. No direct browser table access.
revoke all on all tables in schema public from anon,authenticated;
revoke all on function public.take_rate_limit(text,integer,integer),public.check_in(uuid,uuid,uuid,text),public.leaderboard() from public,anon,authenticated;
grant all on all tables in schema public to service_role;
grant execute on function public.take_rate_limit(text,integer,integer),public.check_in(uuid,uuid,uuid,text),public.leaderboard() to service_role;
alter table public.app_settings enable row level security;
alter table public.profiles enable row level security;
alter table public.identities enable row level security;
alter table public.events enable row level security;
alter table public.registrations enable row level security;
alter table public.attendance enable row level security;
alter table public.points_ledger enable row level security;
alter table public.news enable row level security;
alter table public.rate_limits enable row level security;
